-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Read-only taxi snapshots at explicit boundaries. No interactions or hooks.
local _,ns=...
local Adapter={}
local Copy=ns.NavigationV2WaypointTarget.Copy
local MAX_NODES=2048

local function Public(api,value)
    if type(api.issecretvalue)=='function' then
        local ok,secret=--[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](api.issecretvalue,value)
        if not ok or secret~=false then return nil end
    end
    return value
end--[[APR_DIAG]]; Public = APRTrace("APR-Core/features/navigation/NavigationV2Taxi.lua:12:Public#1", Public)--[[/APR_DIAG]]
local function Call(api,fn,...)
    if type(fn)~='function' then return nil end
    local ok,value=--[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](fn,...)
    if ok then return Public(api,value) end
end--[[APR_DIAG]]; Call = APRTrace("APR-Core/features/navigation/NavigationV2Taxi.lua:19:Call#2", Call)--[[/APR_DIAG]]
local function Integer(value)
    return type(value)=='number' and value==value and value>=0
        and value<=9007199254740991 and value%1==0
end--[[APR_DIAG]]; Integer = APRTrace("APR-Core/features/navigation/NavigationV2Taxi.lua:24:Integer#3", Integer)--[[/APR_DIAG]]

-- No localized-name/slot/proximity matching. Ambiguous API bindings stay unknown.
local function Bindings(catalog)
    local bindings={}
    for _,route in pairs(catalog.byId) do
        for _,stop in ipairs({route.origin,route.destination}) do
            local id=stop.taxiNodeID
            if id then
                local previous=bindings[id]
                if previous==nil then bindings[id]=stop.id
                elseif previous~=stop.id then bindings[id]=false end
            end
        end
    end
    return bindings
end--[[APR_DIAG]]; Bindings = APRTrace("APR-Core/features/navigation/NavigationV2Taxi.lua:30:Bindings#4", Bindings)--[[/APR_DIAG]]

local function NativeNodes(api)
    local mapID=Call(api,api.GetTaxiMapID)
    if not Integer(mapID) or mapID==0 then return end
    local taxi=api.C_TaxiMap
    local raw=type(taxi)=='table' and Call(api,taxi.GetAllTaxiNodes,mapID)
    if type(raw)~='table' then return end
    local result,count={},0
    local total=Call(api,api.NumTaxiNodes)
    local states=type(api.Enum)=='table' and api.Enum.FlightPathState
    for _,value in pairs(raw) do
        count=count+1
        if count>MAX_NODES then return end
        value=Public(api,value)
        if type(value)=='table' then
            local id,slot=Public(api,value.nodeID),Public(api,value.slotIndex)
            local state=Public(api,value.state)
            local kind
            if type(states)=='table' and Integer(state) then
                if state==states.Current then kind='CURRENT'
                elseif state==states.Reachable then kind='REACHABLE'
                elseif state==states.Unreachable then kind='UNREACHABLE' end
            end
            if Integer(id) and id>0 and Integer(slot) and slot>0 then
                -- The legacy type API is available on both clients, and only
                -- called for a validated in-range current-map slot.
                if Integer(total) and slot<=total then
                    kind=Call(api,api.TaxiNodeGetType,slot) or kind
                    result[#result+1]={nodeID=id,slot=slot,kind=kind,
                        fare=kind=='REACHABLE' and Call(api,api.TaxiNodeCost,slot) or nil}
                end
            end
        end
    end
    return result
end--[[APR_DIAG]]; NativeNodes = APRTrace("APR-Core/features/navigation/NavigationV2Taxi.lua:45:NativeNodes#5", NativeNodes)--[[/APR_DIAG]]

function Adapter.Capture(catalog,previous,api,mapOpen)
    api=api or _G
    local observation={revision=(previous and previous.revision or 0)+1,
        nodes=Copy(previous and previous.nodes or {}),routes=Copy(previous and previous.routes or {})}
    local money=Call(api,api.GetMoney)
    local resources={}
    if Integer(money) then resources.money=money end
    if mapOpen~=true then return observation,resources,{} end
    local raw=NativeNodes(api)
    local bindings,byStop,seen,origin,ambiguous=Bindings(catalog),{},{},nil,false
    for _,node in ipairs(raw or {}) do
        local id=bindings[node.nodeID]
        if id then
            if seen[id] then byStop[id]=false else byStop[id]=node;seen[id]=true end
            if node.kind=='CURRENT' then
                if origin then ambiguous=true else origin=id end
            end
        end
    end
    if ambiguous then origin=nil end
    local quotes={}
    for _,route in pairs(catalog.byId) do
        local source,destination=byStop[route.origin.id],byStop[route.destination.id]
        for _,stop in ipairs({route.origin,route.destination}) do
            local node=byStop[stop.id]
            if node and (node.kind=='CURRENT' or node.kind=='REACHABLE') then
                observation.nodes[stop.id]={discovered=true}
            end
        end
        if not raw or not origin or route.origin.id==origin then
            observation.routes[route.id]=nil
            if source and destination and origin==route.origin.id and source.kind=='CURRENT' then
                local reachable
                if destination.kind=='REACHABLE' then reachable=true
                elseif destination.kind=='DISTANT' or destination.kind=='UNREACHABLE' then reachable=false end
                local fare=reachable and Integer(destination.fare) and destination.fare or nil
                local previousRoute=observation.routes[route.id] or (previous and previous.routes[route.id]) or {}
                observation.routes[route.id]={reachable=reachable,fareCopper=fare,rideSeconds=previousRoute.rideSeconds}
                quotes[route.id]={confirmed=reachable==true and fare~=nil,originID=route.origin.id,
                    destinationID=route.destination.id,reachable=reachable,fareCopper=fare}
            end
        end
    end
    return observation,resources,quotes
end--[[APR_DIAG]]; Adapter.Capture = APRTrace("APR-Core/features/navigation/NavigationV2Taxi.lua:81:Adapter.Capture#6", Adapter.Capture)--[[/APR_DIAG]]

function Adapter.OnTaxi(api)
    api=api or _G
    local value=Call(api,api.UnitOnTaxi,'player')
    if type(value)=='boolean' then return value end
end--[[APR_DIAG]]; Adapter.OnTaxi = APRTrace("APR-Core/features/navigation/NavigationV2Taxi.lua:127:Adapter.OnTaxi#7", Adapter.OnTaxi)--[[/APR_DIAG]]

ns.NavigationV2TaxiAdapter=Adapter
return Adapter
